```python
# Setup: instruction-following prompts + strict checkers.
import re
TOPICS=["Write a short story about a lighthouse keeper who finds a message in a bottle.",
"Write a product description for a solar-powered backpack.",
"Write a letter to a city council asking for more bike lanes.",
"Write a blog post about learning to bake bread at home.",
"Explain to a teenager how vaccines train the immune system.",
"Write a poem about the first snowfall of winter.",
"Write a cover letter for a junior data analyst position.",
"Describe a typical day in the life of a beekeeper.",
"Write a review of an imaginary science-fiction movie called The Last Orbit.",
"Write an essay about the benefits and drawbacks of remote work.",
"Write a speech for a high school graduation ceremony.",
"Write a travel guide entry for a small coastal fishing town.",
"Write a dialogue between a robot and an old gardener.",
"Explain the basic rules of chess to a complete beginner.",
"Write a recipe for vegetarian chili with a short introduction.",
"Write a pitch for a startup that refurbishes old smartphones.",
"Summarize the history of the bicycle.",
"Write an advertisement for a neighborhood library's summer reading program.",
"Write a diary entry of an astronaut on a space station.",
"Write a persuasive argument for planting more trees in cities.",
"Write a fairy tale about a fox who wants to fly.",
"Write a guide on how to prepare for a job interview.",
"Write an email to a colleague apologizing for missing a meeting.",
"Describe the water cycle from the point of view of a raindrop.",
"Write a motivational note for someone starting to learn the piano.",
"Explain why the sky is blue to a ten-year-old.",
"Write a short biography of a fictional inventor named Mira Okafor.",
"Write a complaint letter to a hotel about a noisy room.",
"Write a news report about a town that built a giant sandcastle.",
"Write a reflection on what makes a good friend.",
"Write a pep talk for a youth soccer team before a final.",
"Describe your ideal weekend in the mountains."]
PHRASES=["Is there anything else I can help with?","Let me know if you have additional questions.","That is all for today."]
WORDS=["light","river","future","simple","team"]
def mk_inst(kind,R):
    if kind=='min_words': N=R.choice([200,300,400]); return f"Your response should contain at least {N} words.",('min_words',N)
    if kind=='max_words': N=R.choice([50,80,120]); return f"Answer with fewer than {N} words.",('max_words',N)
    if kind=='quotes': return "Wrap your entire response with double quotation marks.",('quotes',)
    if kind=='ps': return "At the end of your response, please explicitly add a postscript starting with P.S.",('ps',)
    if kind=='lower': return "Your entire response should be in English, and in all lowercase letters. No capital letters are allowed.",('lower',)
    if kind=='nocomma': return "In your entire response, refrain from the use of any commas.",('nocomma',)
    if kind=='paras': N=R.choice([3,4,5]); return f"There should be exactly {N} paragraphs. Paragraphs are separated with the markdown divider: ***",('paras',N)
    if kind=='json': return "Wrap your entire output in JSON format.",('json',)
    if kind=='end': ph=R.choice(PHRASES); return f"Finish your response with this exact phrase: {ph} No other words should follow this phrase.",('end',ph)
    if kind=='title': return "Your answer must contain a title, wrapped in double angular brackets, such as <<my title>>.",('title',)
    if kind=='minsent': N=R.choice([10,15,20]); return f"Your response should contain at least {N} sentences.",('minsent',N)
    if kind=='highlight': N=R.choice([2,3]); return f"Highlight at least {N} sections in your answer with markdown, i.e. *highlighted section*.",('highlight',N)
    if kind=='bullets': N=R.choice([3,4,5]); return f"Your answer must contain exactly {N} bullet points. Use markdown bullet points such as:\n* This is point 1.",('bullets',N)
    if kind=='placeholders': N=R.choice([2,3]); return f"The response must contain at least {N} placeholders represented by square brackets, such as [address].",('placeholders',N)
    if kind=='keyword': w=R.choice(WORDS); N=R.choice([3,4]); return f"In your response, the word '{w}' should appear at least {N} times.",('keyword',w,N)
CONFLICT={('min_words','max_words'),('quotes','json'),('nocomma','json'),('end','ps'),('quotes','end'),('json','paras'),('json','bullets'),('json','title'),('json','highlight'),('max_words','minsent'),('max_words','paras'),('quotes','ps'),('json','end'),('json','lower'),('max_words','bullets')}
def ok_combo(ks): return all((a,b) not in CONFLICT and (b,a) not in CONFLICT for a in ks for b in ks if a<b or a>b)
KINDS=['min_words','max_words','quotes','ps','lower','nocomma','paras','json','end','title','minsent','highlight','bullets','placeholders','keyword']
def check_one(spec,resp):
    r=resp.strip(); k=spec[0]
    words=re.findall(r"\b\w+\b",r)
    if k=='min_words': return len(words)>=spec[1]
    if k=='max_words': return len(words)<spec[1]
    if k=='quotes': return len(r)>1 and r[0]=='"' and r[-1]=='"'
    if k=='ps': return bool(re.search(r"\s*p\.\s?s\..*$", r.lower(), re.MULTILINE))
    if k=='lower': return r==r.lower()
    if k=='nocomma': return ',' not in r
    if k=='paras':
        ps=[p for p in re.split(r"\s?\*\*\*\s?",r)]
        return len(ps)==spec[1] and all(p.strip() for p in ps)
    if k=='json':
        v=r
        if v.startswith('`'*3): v=re.sub(r'^`{3}(json|JSON|Json)?','',v).strip()
        if v.endswith('`'*3): v=v[:-3].strip()
        try: json.loads(v); return True
        except Exception: return False
    if k=='end': return r.endswith(spec[1])
